from typing import Optional

from .._models import BaseModel

__all__ = ["CompletionUsage", "CompletionTokensDetails", "PromptTokensDetails", "CostDetails"]


class CompletionTokensDetails(BaseModel):
    """Breakdown of tokens used in a completion."""

    accepted_prediction_tokens: Optional[int] = None
    """
    When using Predicted Outputs, the number of tokens in the prediction that
    appeared in the completion.
    """

    audio_tokens: Optional[int] = None
    """Audio input tokens generated by the model."""

    image_tokens: Optional[int] = None
    """Image output tokens generated by the model."""

    reasoning_tokens: Optional[int] = None
    """Tokens generated by the model for reasoning."""

    rejected_prediction_tokens: Optional[int] = None
    """
    When using Predicted Outputs, the number of tokens in the prediction that did
    not appear in the completion. However, like reasoning tokens, these tokens are
    still counted in the total completion tokens for purposes of billing, output,
    and context window limits.
    """

    text_tokens: Optional[int] = None
    """Text output tokens generated by the model."""


class PromptTokensDetails(BaseModel):
    """Breakdown of tokens used in the prompt."""

    audio_tokens: Optional[int] = None
    """Audio input tokens present in the prompt."""

    cache_write_tokens: Optional[int] = None
    """The unadjusted number of prompt tokens written to cache."""

    cached_tokens: Optional[int] = None
    """Cached tokens present in the prompt."""

    image_tokens: Optional[int] = None
    """Image input tokens present in the prompt."""

    text_tokens: Optional[int] = None
    """Text input tokens present in the prompt."""

    video_tokens: Optional[int] = None
    """Video input tokens present in the prompt."""


class CostDetails(BaseModel):
    """Breakdown of the upstream inference cost, in EGP."""

    upstream_inference_cost: Optional[float] = None
    """Total upstream inference cost."""

    upstream_inference_prompt_cost: Optional[float] = None
    """Upstream cost of the prompt tokens."""

    upstream_inference_completions_cost: Optional[float] = None
    """Upstream cost of the completion tokens."""


class CompletionUsage(BaseModel):
    """Usage statistics for the completion request."""

    completion_tokens: int
    """Number of tokens in the generated completion."""

    prompt_tokens: int
    """Number of tokens in the prompt."""

    total_tokens: int
    """Total number of tokens used in the request (prompt + completion)."""

    completion_tokens_details: Optional[CompletionTokensDetails] = None
    """Breakdown of tokens used in a completion."""

    prompt_tokens_details: Optional[PromptTokensDetails] = None
    """Breakdown of tokens used in the prompt."""

    cost: Optional[float] = None
    """The amount charged for this request, in EGP."""

    cost_details: Optional[CostDetails] = None
    """Breakdown of the upstream inference cost."""

    is_byok: Optional[bool] = None
    """Whether the request was served with a bring-your-own-key provider credential."""
